import { mkdir, readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const defaultSourceUrl = new URL(
  "../../../services/backend/openapi/v1.json",
  import.meta.url,
);
const defaultOutputUrl = new URL("../src/generated/openapi.d.ts", import.meta.url);
const generatedDirectoryUrl = new URL("../src/generated/", import.meta.url);
const header = `/**
 * AUTO-GENERATED from services/backend/openapi/v1.json.
 * Run \`pnpm openapi:generate\`; do not edit this file manually.
 */

`;

const httpMethods = new Set([
  "delete",
  "get",
  "head",
  "options",
  "patch",
  "post",
  "put",
  "trace",
]);
const parameterLocations = new Set(["cookie", "header", "path", "query"]);
const schemaAnnotationKeywords = new Set([
  "$comment",
  "deprecated",
  "description",
  "example",
  "examples",
  "externalDocs",
  "format",
  "readOnly",
  "title",
  "writeOnly",
]);
const schemaValidationKeywords = new Set([
  "default",
  "exclusiveMaximum",
  "exclusiveMinimum",
  "maxItems",
  "maxLength",
  "maxProperties",
  "maximum",
  "minItems",
  "minLength",
  "minProperties",
  "minimum",
  "multipleOf",
  "pattern",
  "uniqueItems",
]);
const schemaStructuralKeywords = new Set([
  "$ref",
  "additionalProperties",
  "allOf",
  "anyOf",
  "const",
  "enum",
  "items",
  "oneOf",
  "properties",
  "required",
  "type",
]);
// `contentMediaType` is how OpenAPI 3.1 says "these bytes are not text". JSON Schema
// 2020-12 dropped `format: binary`, so a multipart file field arrives as
// `{"type": "string", "contentMediaType": "application/octet-stream"}`.
//
// Kept in its own set rather than folded into the annotations, because it is not an
// annotation: it changes the emitted TypeScript. A field carrying it is `Blob`, never
// `string`. Typing an upload field as `string` would let a caller pass a filename or a
// base64 body and get a green type check followed by a runtime failure, which is worse
// than the generator refusing the keyword outright — and refusing it outright is what it
// did until the first upload endpoint shipped.
const schemaContentKeywords = new Set(["contentEncoding", "contentMediaType"]);
const supportedSchemaKeywords = new Set([
  ...schemaAnnotationKeywords,
  ...schemaValidationKeywords,
  ...schemaStructuralKeywords,
  ...schemaContentKeywords,
]);

function compareText(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function assertRecord(value, context) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${context} must be an object.`);
  }
  return value;
}

function sortedEntries(value) {
  return Object.entries(value).sort(([left], [right]) =>
    compareText(left, right),
  );
}

function assertOnlyKeys(value, allowedKeys, context) {
  const unsupported = Object.keys(value)
    .filter((key) => !allowedKeys.has(key))
    .sort(compareText);
  if (unsupported.length > 0) {
    throw new Error(
      `${context} contains unsupported key(s): ${unsupported.join(", ")}`,
    );
  }
}

function propertyName(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/u.test(value)
    ? value
    : JSON.stringify(value);
}

function referenceType(reference) {
  if (typeof reference !== "string") {
    throw new Error("OpenAPI $ref values must be strings.");
  }
  const prefix = "#/components/schemas/";
  if (!reference.startsWith(prefix) || reference.slice(prefix.length).includes("/")) {
    throw new Error(`Unsupported OpenAPI reference: ${reference}`);
  }
  return `components["schemas"][${JSON.stringify(reference.slice(prefix.length))}]`;
}

function validateSchemaKeywords(schema) {
  const unsupported = Object.keys(schema)
    .filter((key) => !supportedSchemaKeywords.has(key))
    .sort(compareText);
  if (unsupported.length > 0) {
    throw new Error(
      `Unsupported OpenAPI schema keyword(s): ${unsupported.join(", ")}`,
    );
  }
}

function literalType(value, context) {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return JSON.stringify(value);
  }
  throw new Error(`${context} values must be JSON primitives.`);
}

function schemaType(schema) {
  if (schema === true) return "unknown";
  if (schema === false) return "never";
  const resolved = assertRecord(schema, "Every generated OpenAPI schema");
  validateSchemaKeywords(resolved);

  if (resolved.$ref !== undefined) {
    if (Object.keys(resolved).some((key) => key !== "$ref")) {
      throw new Error("Sibling keywords next to $ref are not supported.");
    }
    return referenceType(resolved.$ref);
  }
  if (Object.hasOwn(resolved, "const")) {
    return literalType(resolved.const, "OpenAPI const");
  }
  if (resolved.enum !== undefined) {
    if (!Array.isArray(resolved.enum) || resolved.enum.length === 0) {
      throw new Error("OpenAPI enum must be a non-empty array.");
    }
    return resolved.enum
      .map((value) => literalType(value, "OpenAPI enum"))
      .join(" | ");
  }

  const unions = ["anyOf", "oneOf"].filter((key) => resolved[key] !== undefined);
  if (unions.length > 1) {
    throw new Error("A schema cannot combine oneOf and anyOf in this generator.");
  }
  if (unions.length === 1) {
    const members = resolved[unions[0]];
    if (!Array.isArray(members) || members.length === 0) {
      throw new Error(`${unions[0]} must be a non-empty array.`);
    }
    return members.map(schemaType).join(" | ");
  }
  if (resolved.allOf !== undefined) {
    if (!Array.isArray(resolved.allOf) || resolved.allOf.length === 0) {
      throw new Error("allOf must be a non-empty array.");
    }
    return resolved.allOf.map(schemaType).join(" & ");
  }

  const declaredTypes = Array.isArray(resolved.type)
    ? resolved.type
    : [resolved.type];
  if (
    declaredTypes.length === 0 ||
    declaredTypes.some((value) => typeof value !== "string")
  ) {
    throw new Error("OpenAPI schema type must be a string or non-empty string array.");
  }
  if (declaredTypes.length > 1) {
    return declaredTypes
      .map((type) => schemaType({ ...resolved, type }))
      .join(" | ");
  }

  switch (declaredTypes[0]) {
    case "null":
      return "null";
    case "string":
      // Binary content, not text. See `schemaContentKeywords`: this is the only
      // place the distinction can be made, because by the time a caller holds the
      // generated type the schema is gone.
      if (Object.hasOwn(resolved, "contentMediaType")) {
        if (resolved.contentEncoding !== undefined) {
          throw new Error(
            "contentEncoding is not supported: an encoded string is not a Blob and " +
              "the generator must not guess which one the caller should send.",
          );
        }
        return "Blob";
      }
      return "string";
    case "integer":
      if (resolved.format === "int64") {
        throw new Error(
          "OpenAPI int64 cannot be represented safely as a JavaScript number.",
        );
      }
      return "number";
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "array":
      if (!Object.hasOwn(resolved, "items")) {
        throw new Error("Array schemas require items.");
      }
      return `Array<${schemaType(resolved.items)}>`;
    case "object": {
      const properties = assertRecord(
        resolved.properties ?? {},
        "OpenAPI object properties",
      );
      if (
        resolved.required !== undefined &&
        (!Array.isArray(resolved.required) ||
          resolved.required.some((name) => typeof name !== "string"))
      ) {
        throw new Error("OpenAPI required must be an array of property names.");
      }
      const required = new Set(resolved.required ?? []);
      const unknownRequired = [...required].filter(
        (name) => !Object.hasOwn(properties, name),
      );
      if (unknownRequired.length > 0) {
        throw new Error(
          `Required properties are not declared: ${unknownRequired.sort(compareText).join(", ")}`,
        );
      }
      const members = sortedEntries(properties).map(
        ([name, value]) =>
          `${propertyName(name)}${required.has(name) ? "" : "?"}: ${schemaType(value)}`,
      );
      if (resolved.additionalProperties === true) {
        members.push("[key: string]: unknown");
      } else if (
        resolved.additionalProperties !== undefined &&
        resolved.additionalProperties !== false
      ) {
        members.push(
          `[key: string]: ${schemaType(resolved.additionalProperties)}`,
        );
      }
      return members.length === 0
        ? "Record<string, never>"
        : `{ ${members.join("; ")} }`;
    }
    default:
      throw new Error(
        `Unsupported OpenAPI schema type: ${String(declaredTypes[0])}`,
      );
  }
}

function resolveParameter(parameter, context) {
  const resolved = assertRecord(parameter, context);
  assertOnlyKeys(
    resolved,
    new Set([
      "deprecated",
      "description",
      "example",
      "examples",
      "in",
      "name",
      "required",
      "schema",
    ]),
    context,
  );
  if (resolved.$ref !== undefined) {
    throw new Error("Referenced OpenAPI parameters are not supported yet.");
  }
  if (
    typeof resolved.name !== "string" ||
    !parameterLocations.has(resolved.in)
  ) {
    throw new Error(`${context} requires a valid name and location.`);
  }
  if (!Object.hasOwn(resolved, "schema")) {
    throw new Error(`${context} requires a schema.`);
  }
  if (resolved.in === "path" && resolved.required !== true) {
    throw new Error(`Path parameter ${resolved.name} must be required.`);
  }
  return resolved;
}

function mergeParameters(pathParameters = [], operationParameters = [], context) {
  if (!Array.isArray(pathParameters) || !Array.isArray(operationParameters)) {
    throw new Error(`${context} parameters must be arrays.`);
  }
  const merged = new Map();
  for (const candidate of [...pathParameters, ...operationParameters]) {
    const parameter = resolveParameter(candidate, `${context} parameter`);
    const identity = `${parameter.in}\u0000${parameter.name}`;
    merged.set(identity, parameter);
  }
  return [...merged.values()].sort((left, right) => {
    const byLocation = compareText(left.in, right.in);
    return byLocation || compareText(left.name, right.name);
  });
}

function parametersType(parameters) {
  if (parameters.length === 0) return null;
  const groups = new Map();
  for (const parameter of parameters) {
    const entries = groups.get(parameter.in) ?? [];
    entries.push(parameter);
    groups.set(parameter.in, entries);
  }
  const renderedGroups = [...groups.entries()]
    .sort(([left], [right]) => compareText(left, right))
    .map(([location, entries]) => {
      const groupIsOptional = entries.every(
        (parameter) => parameter.required !== true,
      );
      const members = entries.map(
        (parameter) =>
          `${propertyName(parameter.name)}${parameter.required ? "" : "?"}: ${schemaType(parameter.schema)}`,
      );
      return `${propertyName(location)}${groupIsOptional ? "?" : ""}: { ${members.join("; ")} }`;
    });
  return {
    optional: parameters.every((parameter) => parameter.required !== true),
    type: `{ ${renderedGroups.join("; ")} }`,
  };
}

function contentType(content, context) {
  const resolved = assertRecord(content, `${context} content`);
  const entries = sortedEntries(resolved);
  if (entries.length === 0) return "never";
  return `{ ${entries
    .map(([mediaType, media]) => {
      // `multipart/form-data` is accepted for request bodies only, and only because the
      // file API requires it: `05_API_Specification.md:977` specifies it, and a binary
      // upload cannot be JSON without base64 inflating every payload by a third.
      //
      // Responses stay JSON-only. The transport parses every response as JSON and
      // refuses any other media type, so accepting one here would generate a typed
      // client method that cannot read its own reply. Slice 5's download route returns
      // bytes and will need a deliberate decision rather than this one widened.
      const multipartAllowed = context.endsWith("request body");
      if (
        mediaType !== "application/json" &&
        !(multipartAllowed && mediaType === "multipart/form-data")
      ) {
        throw new Error(
          `${context} uses unsupported media type ${mediaType}; the transport accepts application/json only.`,
        );
      }
      const mediaObject = assertRecord(media, `${context} ${mediaType}`);
      assertOnlyKeys(
        mediaObject,
        new Set(["example", "examples", "schema"]),
        `${context} ${mediaType}`,
      );
      if (!Object.hasOwn(mediaObject, "schema")) {
        throw new Error(`${context} ${mediaType} requires a schema.`);
      }
      return `${JSON.stringify(mediaType)}: ${schemaType(mediaObject.schema)}`;
    })
    .join("; ")} }`;
}

function responsesType(responses, context) {
  const resolved = assertRecord(responses, `${context} responses`);
  const entries = sortedEntries(resolved);
  if (entries.length === 0) {
    throw new Error(`${context} requires at least one response.`);
  }
  return `{ ${entries
    .map(([status, response]) => {
      const responseObject = assertRecord(response, `${context} response ${status}`);
      assertOnlyKeys(
        responseObject,
        new Set(["$ref", "content", "description"]),
        `${context} response ${status}`,
      );
      if (responseObject.$ref !== undefined) {
        throw new Error("Referenced OpenAPI responses are not supported yet.");
      }
      const content =
        responseObject.content === undefined
          ? "never"
          : contentType(responseObject.content, `${context} response ${status}`);
      return `${propertyName(status)}: { content: ${content} }`;
    })
    .join("; ")} }`;
}

function securityType(security, knownSchemes, context) {
  if (!Array.isArray(security)) {
    throw new Error(`${context} security must be an array.`);
  }
  if (security.length === 0) return "Array<Record<string, never>>";
  return `Array<${security
    .map((requirement) => {
      const resolved = assertRecord(requirement, `${context} security requirement`);
      const entries = sortedEntries(resolved);
      if (entries.length === 0) return "Record<string, never>";
      return `{ ${entries
        .map(([scheme, scopes]) => {
          if (!knownSchemes.has(scheme)) {
            throw new Error(`${context} references unknown security scheme ${scheme}.`);
          }
          if (
            !Array.isArray(scopes) ||
            scopes.some((scope) => typeof scope !== "string")
          ) {
            throw new Error(`${context} security scopes must be string arrays.`);
          }
          const scopeType =
            scopes.length === 0
              ? "Array<never>"
              : `Array<${scopes.map((scope) => JSON.stringify(scope)).join(" | ")}>`;
          return `${propertyName(scheme)}: ${scopeType}`;
        })
        .join("; ")} }`;
    })
    .join(" | ")}>`;
}

function operationType(operationRecord) {
  const { operation, parameters, knownSchemes, context } = operationRecord;
  const members = [];
  const parameterType = parametersType(parameters);
  if (parameterType) {
    members.push(
      `parameters${parameterType.optional ? "?" : ""}: ${parameterType.type}`,
    );
  }
  if (operation.requestBody !== undefined) {
    const requestBody = assertRecord(
      operation.requestBody,
      `${context} request body`,
    );
    assertOnlyKeys(
      requestBody,
      new Set(["$ref", "content", "description", "required"]),
      `${context} request body`,
    );
    if (requestBody.$ref !== undefined) {
      throw new Error("Referenced request bodies are not supported yet.");
    }
    members.push(
      `requestBody${requestBody.required ? "" : "?"}: { content: ${contentType(
        requestBody.content,
        `${context} request body`,
      )} }`,
    );
  }
  if (operation.security !== undefined) {
    members.push(
      `security: ${securityType(operation.security, knownSchemes, context)}`,
    );
  }
  members.push(`responses: ${responsesType(operation.responses, context)}`);
  return `{ ${members.join("; ")} }`;
}

function securitySchemeType(scheme, name) {
  const resolved = assertRecord(scheme, `Security scheme ${name}`);
  assertOnlyKeys(
    resolved,
    new Set(["description", "in", "name", "type"]),
    `Security scheme ${name}`,
  );
  if (
    resolved.type !== "apiKey" ||
    !parameterLocations.has(resolved.in) ||
    typeof resolved.name !== "string"
  ) {
    throw new Error(
      `Unsupported security scheme ${name}; only apiKey schemes are generated.`,
    );
  }
  return `{ type: "apiKey"; in: ${JSON.stringify(resolved.in)}; name: ${JSON.stringify(resolved.name)} }`;
}

function readComponents(schema) {
  const components = assertRecord(schema.components ?? {}, "OpenAPI components");
  const schemas = assertRecord(
    components.schemas ?? {},
    "OpenAPI component schemas",
  );
  const securitySchemes = assertRecord(
    components.securitySchemes ?? {},
    "OpenAPI security schemes",
  );
  return { schemas, securitySchemes };
}

function generateComponents(schema) {
  const { schemas, securitySchemes } = readComponents(schema);
  const schemaEntries = sortedEntries(schemas).map(
    ([name, value]) => `    ${JSON.stringify(name)}: ${schemaType(value)};`,
  );
  const securityEntries = sortedEntries(securitySchemes).map(
    ([name, value]) =>
      `    ${JSON.stringify(name)}: ${securitySchemeType(value, name)};`,
  );
  return `export interface components {
  schemas: {
${schemaEntries.join("\n")}
  };
  securitySchemes: {
${securityEntries.join("\n")}
  };
}
`;
}

function collectOperations(schema) {
  const paths = assertRecord(schema.paths, "OpenAPI paths");
  const { securitySchemes } = readComponents(schema);
  const knownSchemes = new Set(Object.keys(securitySchemes));
  const operations = [];
  const operationIds = new Set();
  for (const [path, pathItemCandidate] of sortedEntries(paths)) {
    if (!path.startsWith("/")) {
      throw new Error(`OpenAPI path must start with /: ${path}`);
    }
    const pathItem = assertRecord(pathItemCandidate, `Path item ${path}`);
    assertOnlyKeys(
      pathItem,
      new Set([
        "$ref",
        "delete",
        "description",
        "get",
        "head",
        "options",
        "parameters",
        "patch",
        "post",
        "put",
        "summary",
        "trace",
      ]),
      `Path item ${path}`,
    );
    if (pathItem.$ref !== undefined) {
      throw new Error("Referenced OpenAPI path items are not supported yet.");
    }
    const pathParameters = pathItem.parameters ?? [];
    for (const method of [...httpMethods].sort(compareText)) {
      if (!Object.hasOwn(pathItem, method)) continue;
      const context = `${method.toUpperCase()} ${path}`;
      const operation = assertRecord(pathItem[method], context);
      assertOnlyKeys(
        operation,
        new Set([
          "deprecated",
          "description",
          "externalDocs",
          "operationId",
          "parameters",
          "requestBody",
          "responses",
          "security",
          "summary",
          "tags",
        ]),
        context,
      );
      if (
        typeof operation.operationId !== "string" ||
        operation.operationId.length === 0
      ) {
        throw new Error(`Missing operationId for ${context}`);
      }
      if (operationIds.has(operation.operationId)) {
        throw new Error(`Duplicate operationId: ${operation.operationId}`);
      }
      operationIds.add(operation.operationId);
      operations.push({
        context,
        knownSchemes,
        method,
        operation,
        parameters: mergeParameters(
          pathParameters,
          operation.parameters ?? [],
          context,
        ),
        path,
      });
    }
  }
  if (operations.length === 0) {
    throw new Error("OpenAPI must contain at least one operation.");
  }
  return operations;
}

function generatePaths(operations) {
  const grouped = new Map();
  for (const operation of operations) {
    const entries = grouped.get(operation.path) ?? [];
    entries.push(
      `    ${operation.method}: operations[${JSON.stringify(operation.operation.operationId)}];`,
    );
    grouped.set(operation.path, entries);
  }
  return `export interface paths {
${[...grouped.entries()]
  .sort(([left], [right]) => compareText(left, right))
  .map(
    ([path, entries]) =>
      `  ${JSON.stringify(path)}: {\n${entries.join("\n")}\n  };`,
  )
  .join("\n")}
}
`;
}

function generateOperations(operations) {
  return `export interface operations {
${operations
  .toSorted((left, right) =>
    compareText(left.operation.operationId, right.operation.operationId),
  )
  .map(
    (operation) =>
      `  ${JSON.stringify(operation.operation.operationId)}: ${operationType(operation)};`,
  )
  .join("\n")}
}
`;
}

export function renderTypesFromSchema(source) {
  const schema = assertRecord(source, "OpenAPI document");
  if (!String(schema.openapi ?? "").startsWith("3.1.")) {
    throw new Error("The local generator requires OpenAPI 3.1.");
  }
  if (!schema.info || typeof schema.info !== "object") {
    throw new Error("The OpenAPI document requires info metadata.");
  }
  if (schema.security !== undefined) {
    throw new Error(
      "Document-level OpenAPI security is not supported; declare it per operation.",
    );
  }
  if (schema.servers !== undefined) {
    throw new Error(
      "OpenAPI servers are not supported by the fixed same-origin typed client.",
    );
  }
  const operations = collectOperations(schema);
  return `${header}${generatePaths(operations)}
${generateComponents(schema)}
${generateOperations(operations)}`;
}

async function renderTypes(sourceUrl) {
  const source = JSON.parse(await readFile(sourceUrl, "utf8"));
  return renderTypesFromSchema(source);
}

function parseArguments(arguments_) {
  const [mode, ...rest] = arguments_;
  if (mode !== "--write" && mode !== "--check") {
    throw new Error(
      "Usage: node scripts/openapi-contract.mjs <--write|--check> [--source path] [--output path]",
    );
  }
  let sourceUrl = defaultSourceUrl;
  let outputUrl = defaultOutputUrl;
  for (let index = 0; index < rest.length; index += 2) {
    const option = rest[index];
    const value = rest[index + 1];
    if (!value || (option !== "--source" && option !== "--output")) {
      throw new Error(`Invalid generator option: ${String(option)}`);
    }
    const resolved = pathToFileURL(resolve(value));
    if (option === "--source") sourceUrl = resolved;
    if (option === "--output") outputUrl = resolved;
  }
  return { mode, outputUrl, sourceUrl };
}

async function main(arguments_ = process.argv.slice(2)) {
  const { mode, outputUrl, sourceUrl } = parseArguments(arguments_);
  const generated = await renderTypes(sourceUrl);
  const outputPath = fileURLToPath(outputUrl);
  if (mode === "--write") {
    const outputDirectory =
      outputUrl === defaultOutputUrl
        ? fileURLToPath(generatedDirectoryUrl)
        : fileURLToPath(new URL(".", outputUrl));
    await mkdir(outputDirectory, { recursive: true });
    await writeFile(outputPath, generated, { encoding: "utf8" });
    process.stdout.write("Wrote deterministic TypeScript OpenAPI types.\n");
    return;
  }

  let existing;
  try {
    existing = await readFile(outputPath, "utf8");
  } catch (error) {
    if (error && error.code === "ENOENT") {
      throw new Error(
        "Generated OpenAPI types are missing; run `pnpm openapi:generate`.",
      );
    }
    throw error;
  }
  if (existing !== generated) {
    throw new Error(
      "Generated OpenAPI types are stale; run `pnpm openapi:generate` and review the diff.",
    );
  }
  process.stdout.write("Generated TypeScript OpenAPI types are current.\n");
}

const invokedPath = process.argv[1]
  ? pathToFileURL(process.argv[1]).href
  : undefined;
if (invokedPath === import.meta.url) {
  await main();
}
